// swift-tools-version: 6.0
// Grains core packages. The macOS app (App/) is generated by XcodeGen from project.yml and
// depends on these products; `swift test` at the repo root runs the headless test suites.
import PackageDescription

let package = Package(
    name: "Grains",
    platforms: [.macOS(.v15)],
    products: [
        .library(name: "GrainsCore", targets: ["GrainsCore"]),
        .library(name: "GrainsReports", targets: ["GrainsReports"]),
        .library(name: "GrainsMCP", targets: ["GrainsMCP"]),
        .executable(name: "grains-mcp", targets: ["grains-mcp"]),
    ],
    targets: [
        // Models, entry parser, SQLite store, timer engine, recovery. No UI, no network.
        .target(
            name: "GrainsCore",
            linkerSettings: [.linkedLibrary("sqlite3")]
        ),
        // Week math, chart series, statistics, CSV export. Pure functions over GrainsCore types.
        .target(name: "GrainsReports", dependencies: ["GrainsCore"]),
        // Read-only MCP server implementation (JSON-RPC over stdio), testable without a process.
        .target(name: "GrainsMCP", dependencies: ["GrainsCore", "GrainsReports"]),
        // Thin executable wrapper around GrainsMCP; bundled inside Grains.app.
        .executableTarget(name: "grains-mcp", dependencies: ["GrainsMCP"]),

        .testTarget(name: "GrainsCoreTests", dependencies: ["GrainsCore"]),
        .testTarget(name: "GrainsReportsTests", dependencies: ["GrainsReports"]),
        .testTarget(name: "GrainsMCPTests", dependencies: ["GrainsMCP"]),
    ],
    swiftLanguageModes: [.v6]
)
